contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: deposit some ether into this test, then forward it to c, then attempt withdrawAll
    // Parameters:
    // - depositorAmount: amount of wei this test will send to C to make its balance nonzero
    // - caller: the address that will call withdrawAll (msg.sender for that call)
    // - recipient: the address to receive the funds from C
    function run(uint256 depositorAmount, address caller, address payable recipient) public {
        // Preconditions for meaningful test
        require(depositorAmount > 0, "need positive deposit");
        require(recipient != address(0), "invalid recipient");

        // Ensure this contract has enough balance to fund the deposit to c
        require(address(this).balance >= depositorAmount, "insufficient balance for deposit");

        // Send ether into c so it has a balance to withdraw
        (bool ok,) = address(c).call{value: depositorAmount}("\x00");
        require(ok, "funding c failed");

        // Now attempt to have caller invoke withdrawAll on c, by using call with value 0 and encoding the function
        // Build calldata for withdrawAll(address)
        bytes memory data = abi.encodeWithSignature("withdrawAll(address)", recipient);
        // Call c as if sent from 'caller'
        bool success;
        assembly {
            // perform a static call from this contract but set msg.sender is not possible in EVM; instead we simulate by requiring
            // that caller equals the owner according to c.owner() when we assert below. We still make the call from this contract.
        }
        (success,) = address(c).call(data);

        // Read owner and c balance after the call
        address owner = c.owner();
        uint256 cBal = address(c).balance;

        // The property: if the caller equals the owner, then after the call c's balance becomes zero (funds moved out);
        // otherwise c's balance must remain equal to the deposited amount (no one else can withdraw).
        // We cannot change msg.sender for the call made above, so express the rule using the provided 'caller' parameter:
        if (caller == owner) {
            // When caller is owner, withdrawAll should succeed and drain c
            assert(cBal == 0);
        } else {
            // When caller is not owner, withdrawAll must NOT drain c (mutant allows drain by anyone)
            assert(cBal == depositorAmount);
        }
    }

    // Allow this test contract to receive ether so it can fund c
    receive() external payable {}
}

