        // and its public owner() getter call succeeds. We detect success by a low-level staticcall
        // to owner() selector and assert it returns true.
        bytes memory sig = abi.encodeWithSignature("owner()");
        (bool ok, ) = address(c).staticcall(sig);
        assertTrue(ok);
    }
}
